// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 2 ether);
        (bool ok1,) = address(c).call{value: 1 ether}("");
        assertTrue(ok1);
        (bool ok2,) = address(c).call{value: 1 ether}("");
        assertTrue(ok2);
        assertEq(c.depositsCount(), 2);
    }
}
